def transform(grid):
    """Return the 3x3 non-background panel that uses three colors."""
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {grid[y][x] for y, x in cells}
            if len(colors) == 3:
                y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
                x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
                return [row[x0:x1+1] for row in grid[y0:y1+1]]
    raise ValueError('No three-color non-background component found')


if __name__ == '__main__':
    pass
